		float range_to = randomizer->random_volume_offset_db;

		float VOLUME_OFFSET_DB = range_from + Math::randf() * (range_to - range_from);
		volume_scale = Math::db_to_linear(VOLUME_OFFSET_DB);
	}

	if (playing.is_valid()) {
