	TypedArray<Transform3D> camera_offsets;

	OpenXRAPI *openxr_api = OpenXRAPI::get_singleton();
	ERR_FAIL_NULL_V(openxr_api, camera_offsets);

	if (p_tracker_name == XR_TRACKER_INSET) {
