		XRServer *xr_server = XRServer::get_singleton();
		ERR_FAIL_NULL_V(xr_server, camera_offsets);

		double WORLD_SCALE = xr_server->get_world_scale();

		for (uint32_t v = 2; v < 4; v++) {
			Transform3D t;
			openxr_api->get_view_offset(v, t);

			// Apply our world scale
